<?php
require __DIR__.'/../vendor/autoload.php';
$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use App\Models\{IntegrationSetting,Order,PaymentAttempt,Product};use App\Services\Sslcommerz;use Illuminate\Support\Facades\{DB,Http};
function check($ok,$message){if(!$ok)throw new RuntimeException($message);echo "PASS: $message\n";}
function fakeGateway($responses){Http::swap(new Illuminate\Http\Client\Factory);Http::preventStrayRequests();Http::fake($responses);}
DB::beginTransaction();try{
$setting=IntegrationSetting::where('provider','sslcommerz')->firstOrFail();$setting->update(['settings'=>['store_id'=>'testbox','mode'=>'test','status'=>true],'credentials'=>['store_password'=>'qwerty']]);
$product=Product::create(['name'=>'Payment fixture','category_id'=>App\Models\Category::firstOrFail()->id,'regular_price'=>100,'stock'=>5,'status'=>true]);
function orderFixture(){global $product;$order=Order::create(['customer_name'=>'Sandbox Test','phone'=>'01700000000','address'=>'Fixture address','area'=>'inside_dhaka','payment_method'=>'sslcommerz','payment_status'=>'unpaid','status'=>'pending','subtotal'=>100,'delivery_fee'=>80,'total'=>180,'stock_reserved'=>true]);$order->items()->create(['product_id'=>$product->id,'product_name'=>$product->name,'quantity'=>1,'unit_price'=>100,'total'=>100]);$product->decrement('stock');return $order;}
$gateway=new Sslcommerz;$order=orderFixture();Http::preventStrayRequests();fakeGateway(['*gwprocess/v4/api.php'=>Http::response(['status'=>'SUCCESS','GatewayPageURL'=>'https://sandbox.sslcommerz.com/EasyCheckOut/test'])]);
check(str_starts_with($gateway->initiate($order),'https://sandbox.sslcommerz.com/'),'Sandbox session initiation');Http::assertSent(fn($r)=>$r['total_amount']==180 && $r['currency']==='BDT' && isset($r['ipn_url']));check(true,'Server amount and callback payload');
$attempt=PaymentAttempt::where('order_id',$order->id)->firstOrFail();$valid=['status'=>'VALID','tran_id'=>$attempt->transaction_id,'val_id'=>'fixture-validation','amount'=>'180.00','currency'=>'BDT','risk_level'=>'0'];
foreach(['status'=>'INVALID','tran_id'=>'other','amount'=>'1.00','currency'=>'USD','val_id'=>'wrong'] as $key=>$value){fakeGateway(['*validationserverAPI.php*'=>Http::response(array_replace($valid,[$key=>$value]))]);check(!$gateway->verify($attempt,'fixture-validation') && $order->fresh()->payment_status==='unpaid','Rejects invalid '.$key);}
fakeGateway(['*validationserverAPI.php*'=>Http::response($valid)]);check($gateway->verify($attempt,'fixture-validation') && $order->fresh()->payment_status==='paid','Verified payment updates matching order');check($gateway->verify($attempt,'fixture-validation') && $product->fresh()->stock===4,'Duplicate validation is idempotent');
$r=Illuminate\Http\Request::create('/payments/sslcommerz/ipn','POST',['tran_id'=>$attempt->transaction_id,'val_id'=>'fixture-validation']);$app->instance('request',$r);check((new App\Http\Controllers\SslcommerzController)->ipn($r,$gateway)->getStatusCode()===200,'IPN validates payment');
fakeGateway(['*merchantTransIDvalidationAPI.php*'=>Http::response(['element'=>[['tran_id'=>$attempt->transaction_id,'status'=>'FAILED']]])]);$gateway->verifyFailure($attempt);check($order->fresh()->status==='pending' && $order->fresh()->payment_status==='paid','Failure cannot undo paid order');
$order2=orderFixture();fakeGateway(['*gwprocess/v4/api.php'=>Http::response(['status'=>'SUCCESS','GatewayPageURL'=>'https://sandbox.sslcommerz.com/EasyCheckOut/test'])]);$gateway->initiate($order2);$attempt2=PaymentAttempt::where('order_id',$order2->id)->firstOrFail();fakeGateway(['*merchantTransIDvalidationAPI.php*'=>Http::response(['element'=>[['tran_id'=>$attempt2->transaction_id,'status'=>'CANCELLED']]])]);$gateway->verifyFailure($attempt2);$gateway->verifyFailure($attempt2);check($order2->fresh()->status==='cancelled' && $product->fresh()->stock===4,'Cancellation restores stock once');
fakeGateway(['*validationserverAPI.php*'=>Http::response(array_replace($valid,['tran_id'=>$attempt2->transaction_id,'val_id'=>'late-validation']))]);check($gateway->verify($attempt2,'late-validation') && $order2->fresh()->status==='on_hold','Late payment held for review');
$order3=orderFixture();fakeGateway(['*gwprocess/v4/api.php'=>Http::response(['status'=>'FAILED'])]);try{$gateway->initiate($order3);throw new RuntimeException('Expected error');}catch(Illuminate\Validation\ValidationException $e){}check($order3->fresh()->status==='cancelled' && $product->fresh()->stock===4,'Initiation failure releases inventory');
$online=Illuminate\Http\Request::create('/checkout','POST',['customer_name'=>'Payment fixture','phone'=>'01700000000','address'=>'Test address','area'=>'inside_dhaka','payment_method'=>'sslcommerz','policy_accepted'=>true,'items'=>[['product_id'=>$product->id,'quantity'=>1]]]);$online->headers->set('X-Inertia','true');$app->instance('request',$online);$online->setLaravelSession($app->make('session.store'));
fakeGateway(['*gwprocess/v4/api.php'=>Http::response(['status'=>'SUCCESS','GatewayPageURL'=>'https://sandbox.sslcommerz.com/EasyCheckOut/test'])]);
$redirect=(new App\Http\Controllers\CheckoutController)->store($online);check($redirect->getStatusCode()===409 && $redirect->headers->has('X-Inertia-Location'),'Online checkout redirects to hosted payment page');
$onlineAttempt=PaymentAttempt::latest('id')->firstOrFail();fakeGateway(['*validationserverAPI.php*'=>Http::response(array_replace($valid,['tran_id'=>$onlineAttempt->transaction_id,'val_id'=>'browser-validation']))]);
$callback=Illuminate\Http\Request::create('/payments/sslcommerz/return/'.$onlineAttempt->transaction_id.'/success','POST',['val_id'=>'browser-validation']);$kernel=$app->make(Illuminate\Contracts\Http\Kernel::class);$result=$kernel->handle($callback);check($result->getStatusCode()===303 && count($result->headers->getCookies())===0 && $onlineAttempt->order->fresh()->payment_status==='paid','CSRF-exempt callback verifies payment without replacing session cookie');
$setting->update(['settings'=>['status'=>false]]);check(!$gateway->available(),'Disabled gateway unavailable');check(!array_key_exists('credentials',$attempt->toArray()),'Credentials hidden');
}finally{DB::rollBack();}


